#include "NotificationBridge.h"
#include <QJsonDocument>
#include <QJsonParseError>
#include <QRegularExpression>
#include <QDBusPendingCallWatcher>
#include <QDBusPendingReply>
namespace{
constexpr auto service="org.freedesktop.Notifications";constexpr auto path="/org/freedesktop/Notifications";
bool opaque(const QJsonValue&v){static const QRegularExpression re("^[A-Za-z0-9_-]{1,128}$");return v.isString()&&re.match(v.toString()).hasMatch();}
bool keys(const QJsonObject&o,const QStringList&names){if(o.size()!=names.size())return false;for(const auto&n:names)if(!o.contains(n))return false;return QJsonDocument(o).toJson(QJsonDocument::Compact).size()<=4096;}
}
bool NotificationBridge::validInput(const QJsonObject&o){return keys(o,{"v","id","kind"})&&o.value("v")==1&&opaque(o.value("id"))&&QStringList{"completion","approval","attention"}.contains(o.value("kind").toString());}
bool NotificationBridge::validOutput(const QJsonObject&o){if(o.value("v")!=1||!opaque(o.value("ownerRevision")))return false;const auto event=o.value("event").toString();if(event=="ready")return keys(o,{"v","event","available","actions","ownerRevision"})&&o.value("available").isBool()&&o.value("actions").isBool()&&(o.value("available").toBool()||!o.value("actions").toBool());if(event=="result")return keys(o,{"v","event","id","status","ownerRevision"})&&opaque(o.value("id"))&&QStringList{"delivered","unavailable","failed"}.contains(o.value("status").toString());return event=="open"&&keys(o,{"v","event","id","ownerRevision"})&&opaque(o.value("id"));}
NotificationBridge::NotificationBridge(QDBusConnection bus,QObject*parent):QObject(parent),bus_(std::move(bus)),watcher_(service,bus_,QDBusServiceWatcher::WatchForOwnerChange,this){connect(&watcher_,&QDBusServiceWatcher::serviceOwnerChanged,this,[this](const QString&,const QString&,const QString&next){if(started_&&!closed_)setOwner(next);});}
void NotificationBridge::announce(){emit frame({{"v",1},{"event","ready"},{"available",available_},{"actions",available_&&actions_},{"ownerRevision",revision_}});}
void NotificationBridge::result(const QString&id,const QString&status,const QString&revision){emit frame({{"v",1},{"event","result"},{"id",id},{"status",status},{"ownerRevision",revision}});}
void NotificationBridge::start(){if(started_||closed_)return;started_=true;auto msg=QDBusMessage::createMethodCall("org.freedesktop.DBus","/org/freedesktop/DBus","org.freedesktop.DBus","GetNameOwner");msg<<QString(service);const auto generation=generation_;auto*pending=new QDBusPendingCallWatcher(bus_.asyncCall(msg,2000),this);connect(pending,&QDBusPendingCallWatcher::finished,this,[this,pending,generation]{QDBusPendingReply<QString> reply=*pending;pending->deleteLater();if(closed_||generation_!=generation)return;setOwner(reply.isError()?QString():reply.value());});}
void NotificationBridge::closeAt(const QString&owner,uint id){if(owner.isEmpty())return;auto msg=QDBusMessage::createMethodCall(owner,path,service,"CloseNotification");msg<<id;bus_.asyncCall(msg,2000);}
void NotificationBridge::setOwner(const QString&next){if(closed_)return;
 if(!owner_.isEmpty()){bus_.disconnect(owner_,path,service,"ActionInvoked",this,SLOT(action(uint,QString,QDBusMessage)));bus_.disconnect(owner_,path,service,"NotificationClosed",this,SLOT(notificationClosed(uint,uint,QDBusMessage)));for(auto i=active_.cbegin();i!=active_.cend();++i)closeAt(owner_,i.key());}
 active_.clear();if(busy_){result(current_.value("id").toString(),"failed",revision_);busy_=false;current_={};}while(!queue_.isEmpty())result(queue_.dequeue().value("id").toString(),"unavailable",revision_);
 ++serial_;revision_=QString::number(++generation_);owner_=next;available_=false;actions_=false;if(owner_.isEmpty()){announce();return;}
 bus_.connect(owner_,path,service,"ActionInvoked",this,SLOT(action(uint,QString,QDBusMessage)));bus_.connect(owner_,path,service,"NotificationClosed",this,SLOT(notificationClosed(uint,uint,QDBusMessage)));
 auto msg=QDBusMessage::createMethodCall(owner_,path,service,"GetCapabilities");const auto generation=generation_;auto*pending=new QDBusPendingCallWatcher(bus_.asyncCall(msg,2000),this);connect(pending,&QDBusPendingCallWatcher::finished,this,[this,pending,generation]{QDBusPendingReply<QStringList> reply=*pending;pending->deleteLater();if(closed_||generation_!=generation)return;available_=!reply.isError();actions_=available_&&reply.value().contains("actions");announce();});
}
bool NotificationBridge::acceptLine(const QByteArray&line){if(closed_||line.size()>4096)return false;QJsonParseError error;const auto doc=QJsonDocument::fromJson(line,&error);if(error.error!=QJsonParseError::NoError||!doc.isObject()||!validInput(doc.object()))return false;const auto input=doc.object();if(!available_||queue_.size()+(busy_?1:0)>=16){result(input.value("id").toString(),"unavailable",revision_);return true;}queue_.enqueue(input);pump();return true;}
void NotificationBridge::pump(){if(closed_||busy_||queue_.isEmpty()||!available_)return;current_=queue_.dequeue();busy_=true;const auto serial=++serial_,generation=generation_;const auto input=current_;const auto owner=owner_,revision=revision_;const auto kind=input.value("kind").toString();
 QString title,body;if(kind=="completion"){title="Tilde finished";body="Open Tilde to view the reply.";}else if(kind=="approval"){title="Tilde needs your approval";body="Open Tilde to review the exact action.";}else{title="Tilde needs attention";body="Open Tilde to inspect the current status.";}
 auto msg=QDBusMessage::createMethodCall(owner,path,service,"Notify");msg<<QString("Tilde")<<uint(0)<<QString("tilde-gui")<<title<<body<<(actions_?QStringList{"open","Open Tilde"}:QStringList{})<<QVariantMap{}<<int(-1);
 auto*pending=new QDBusPendingCallWatcher(bus_.asyncCall(msg,2000),this);connect(pending,&QDBusPendingCallWatcher::finished,this,[this,pending,input,owner,revision,generation,serial]{QDBusPendingReply<uint> reply=*pending;pending->deleteLater();if(closed_||generation_!=generation||serial_!=serial){if(!reply.isError()&&reply.value())closeAt(owner,reply.value());return;}busy_=false;current_={};if(reply.isError()||!reply.value())result(input.value("id").toString(),"failed",revision);else{if(active_.size()>=16){auto i=active_.begin();closeAt(owner,i.key());active_.erase(i);}active_[reply.value()]={input.value("id").toString(),revision};result(input.value("id").toString(),"delivered",revision);}pump();});
}
void NotificationBridge::action(uint id,const QString&key,const QDBusMessage&message){if(closed_||!available_||!actions_||message.service()!=owner_||key!="open"||!active_.contains(id))return;const auto found=active_.take(id);if(found.revision!=revision_)return;closeAt(owner_,id);emit frame({{"v",1},{"event","open"},{"id",found.event},{"ownerRevision",revision_}});}
void NotificationBridge::notificationClosed(uint id,uint,const QDBusMessage&message){if(message.service()==owner_)active_.remove(id);}
void NotificationBridge::close(){if(closed_)return;closed_=true;++serial_;if(busy_)result(current_.value("id").toString(),"failed",revision_);busy_=false;while(!queue_.isEmpty())result(queue_.dequeue().value("id").toString(),"unavailable",revision_);for(auto i=active_.cbegin();i!=active_.cend();++i)closeAt(owner_,i.key());active_.clear();}
